A class makes the length operation and the membership operation consult its own hooks, and all three results are printed. What does this program print?

class Bag:
    def __init__(self, items):
        self.items = items
    def __len__(self):
        return len(self.items)
    def __contains__(self, x):
        return x in self.items

b = Bag([1, 2, 3])
print(len(b), 2 in b, 9 in b, b.items)

A class defines both text forms, and the object is printed inside a list, inside a formatted value, and by each of the two conversions. What does this program print?

class Money:
    def __init__(self, cents):
        self.cents = cents
    def __repr__(self):
        return f"Money({self.cents})"
    def __str__(self):
        return f"{self.cents}c"

m = Money(250)
print([m], f"{m}", str(m), repr(m))

A class compares its objects without regard to letter case but hashes them with the case left in, and both objects are put into one set. What does this program print?

class Tag:
    def __init__(self, name):
        self.name = name
    def __eq__(self, other):
        return isinstance(other, Tag) and self.name.lower() == other.name.lower()
    def __hash__(self):
        return hash(self.name)

print(Tag("x") == Tag("X"), len({Tag("x"), Tag("X")}))

A subclass defines a method the parent also defines, and both classes are instantiated and asked the same question. What does this program print?

class Shape:
    def describe(self):
        return "shape"

class Square(Shape):
    def describe(self):
        return "square"

print([s.describe() for s in [Shape(), Square()]])

A child class sets up the parent's attributes, then its own method wraps the parent's answer rather than replacing it. What does this program print?

class Base:
    def __init__(self, name):
        self.name = name
    def tag(self):
        return "base:" + self.name

class Child(Base):
    def __init__(self, name, extra):
        super().__init__(name)
        self.extra = extra
    def tag(self):
        return "child:" + super().tag() + ":" + str(self.extra)

c = Child("k", 2)
print(c.tag(), c.name, c.extra)

A class names two parents that both define the method, and the program asks the object and then asks for the class in the second slot of its search order. What does this program print?

class A:
    def who(self):
        return "A"

class B(A):
    def who(self):
        return "B"

class C(A):
    def who(self):
        return "C"

class D(B, C):
    pass

print(D().who(), D.__mro__[1].__name__)

A class computes one of its attributes from two stored ones, and the program reads it and then inspects what the object actually holds. What does this program print?

class Rect:
    def __init__(self, w, h):
        self.w = w
        self.h = h
    @property
    def area(self):
        return self.w * self.h

r = Rect(3, 4)
print(r.area, r.__dict__["w"], "area" in r.__dict__)

One fault in a family descends from a custom parent and another does not, and each is raised in turn with two handlers in the loop. What does this program print?

class AppError(Exception):
    pass

class NotFound(AppError):
    pass

def get(k):
    if k == "x":
        raise NotFound("x")
    raise ValueError("other")

for k in ["x", "y"]:
    try:
        get(k)
    except AppError as err:
        print("app", type(err).__name__)
    except ValueError as err:
        print("val", type(err).__name__)

A custom fault builds its own text from two numbers, stores them, and is then raised and caught. What does this program print?

class Insufficient(Exception):
    def __init__(self, need, have):
        super().__init__(f"need {need} have {have}")
        self.need = need
        self.have = have

try:
    raise Insufficient(10, 3)
except Insufficient as err:
    print(str(err), err.need - err.have)

A context manager is written by hand with both hooks, its body runs without a fault, and the exit hook reports what it saw. What does this program print?

class Guard:
    def __init__(self, name):
        self.name = name
    def __enter__(self):
        print("enter", self.name)
        return self.name
    def __exit__(self, exc_type, exc, tb):
        print("exit", self.name, exc_type is None)
        return False

with Guard("a") as g:
    print("body", g)
print("after")

One check is written once and run over a table of cases, with the outcome of each recorded and the number of failures counted. What does this program print?

def check(v, expected):
    assert v * v == expected

cases = [(2, 4), (3, 9), (4, 15)]
results = []
for v, want in cases:
    try:
        check(v, want)
        results.append("ok")
    except AssertionError:
        results.append("fail")
print(results, results.count("fail"))

A test computes a total and asserts something untrue about it, and the whole body is wrapped so the fault is visible. What does this program actually print?

def run():
    try:
        total = 1 + 1
        assert total == 3
        print("passed")
    except AssertionError:
        print("failed")

run()
print("done")

A routine averages a list by dividing its total by its length, and it is first handed an empty list with the fault caught. What does this program actually print?

def mean(values):
    return sum(values) / len(values)

try:
    print(mean([]))
except ZeroDivisionError:
    print("ZeroDivisionError")
print(mean([2, 4]))

A class takes a list that may be left out, stores whatever it was given without replacing a missing one, and the caller then appends to it. What does this program actually print?

class Bag:
    def __init__(self, items=None):
        self.items = items

a = Bag()
try:
    a.items.append(1)
    print("appended")
except AttributeError:
    print("AttributeError", a.items)
print(a.items is None)

A recursive routine counts every request it receives, including the ones it answers from its table, and the requested value is then read out. The printed number packs the count in the thousands and the value in the units. What number is printed?

calls = 0
def fib(n, memo=None):
    global calls
    calls += 1
    if memo is None:
        memo = {}
    if n < 2:
        return n
    if n in memo:
        return memo[n]
    memo[n] = fib(n - 1, memo) + fib(n - 2, memo)
    return memo[n]

value = fib(12)
print(calls * 1000 + value)

A class holds one method that needs nothing but its arguments and one that is handed the class itself, and both are called on the class and on an object. Which pair names what this program prints and why?

class Util:
    @staticmethod
    def norm(x, y):
        return (x * x + y * y) ** 0.5
    @classmethod
    def origin(cls):
        return cls.__name__

print(Util.norm(3, 4), Util.origin(), Util().norm(0, 5))

The same generator is consumed twice, once by a loop that adds each value and once by a built-in that adds them, and a third reader takes the values again. What does this program print?

def items():
    for v in [1, 2, 3]:
        yield v

loop_total = 0
for v in items():
    loop_total += v
gen_total = sum(items())
print(loop_total, gen_total, list(items()))

A class compares its objects by a stored total but derives its hash from the object's own address, and both objects are put into one set. What does this program actually print?

class Order:
    def __init__(self, total):
        self.total = total
    def __eq__(self, other):
        return self.total == other.total
    def __hash__(self):
        return hash(id(self))

a = Order(5)
b = Order(5)
print(a == b, len({a, b}))

Two bodies share one list, one of them is run on its own first, and then the three calls are printed in the order they were made. What does this program actually print?

seen = []

def first():
    seen.append(1)
    return len(seen)

def second():
    seen.append(2)
    return len(seen)

alone = second()
print(alone, first(), second())

A routine yields three values, a loop adds them into one total and a second call to the same routine is handed to a built-in that adds them, with the two totals packed into one printed number. What number is printed?

def items():
    for v in [2, 4, 6]:
        yield v

loop_total = 0
for v in items():
    loop_total += v
print(loop_total * 10 + sum(items()))

A fault from a family under a built-in base is caught by a handler for the family, and the handler prints the fault's own class name and its text. Which pair names what this program prints and why?

class Base(Exception):
    pass

class Child(Base):
    pass

try:
    raise Child("c")
except Base as err:
    print("caught", type(err).__name__, str(err))

A stand-in keeps the identifiers it is handed, and the program saves two records through it and then reports the record and its size. Which pair names what this program prints and why?

class FakeStore:
    def __init__(self):
        self.saved = []
    def save(self, row):
        self.saved.append(row["id"])

store = FakeStore()
for row in [{"id": 1}, {"id": 2}]:
    store.save(row)
print(store.saved, len(store.saved))
